// IconSource 按名字返回一颗图标的 gui.IconSource（24×24 viewBox，nonzero 填充）。
// 调用方再用 ui.Icon(src).Size(dip) 指定实际尺寸。
// 名字不认识返回 nil；内嵌数据自己解不开属于构建产物坏了，直接 panic。
//
// svg.Source 自带一份栅格缓存且内部加锁，可以跨窗口、跨帧共享，所以每颗图标只
// 解析一次。
func IconSource(name string) gui.IconSource {
	d, ok := iconPath(name)
	if !ok {
		return nil
	}
	iconSourcesMu.Lock()
	defer iconSourcesMu.Unlock()
	if src, ok := iconSources[name]; ok {
		return src
	}
	// 包裹成完整 SVG 文档，oksvg 需要 <svg> 根元素才能解析 viewBox。
	doc := fmt.Sprintf(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="%s"/></svg>`, d)
	src, err := svg.Parse(strings.NewReader(doc))
	if err != nil {
		panic(fmt.Sprintf("theme/fonts: icon %q does not parse: %v", name, err))
	}
	iconSources[name] = src
	return src
}

var (
	iconOnce      sync.Once
	iconPaths     map[string]string
	iconSourcesMu sync.Mutex
	iconSources   = map[string]*svg.Source{}
)

// iconPath looks one icon up in the embedded blob, which is decompressed and
// indexed once per process. Doing it per call would gunzip and split the whole
// table for every icon in every frame.
func iconPath(name string) (string, bool) {
	iconOnce.Do(func() {
		reader, err := gzip.NewReader(bytes.NewReader(svgIconData))
		if err != nil {
			panic(fmt.Sprintf("theme/fonts: icon table: %v", err))
		}
		blob, err := io.ReadAll(reader)
		reader.Close()
		if err != nil {
			panic(fmt.Sprintf("theme/fonts: icon table: %v", err))
		}
		iconPaths = map[string]string{}
		for _, line := range strings.Split(string(blob), "\n") {
			if i := strings.IndexByte(line, ':'); i > 0 {
				iconPaths[line[:i]] = line[i+1:]
			}
		}
	})
	path, ok := iconPaths[name]
	return path, ok
}
